sql.if:
AND EXISTS (
    SELECT 1 FROM performance_schedule ps
     WHERE ps.performance_id = p.id
       AND CAST(ps.show_at AS TIME) >= #{f.timeSlotFrom}
       AND CAST(ps.show_at AS TIME) <  #{f.timeSlotTo}
)

mapper.select:
SELECT COUNT(*)
  FROM performance p
 WHERE 1 = 1

AND p.category = #{f.category}
AND MONTH(p.start_date) = #{f.month}
AND p.venue = #{f.venue}
